import { jsx as _jsx } from "react/jsx-runtime";
import { createContext, useContext } from "react";
/**
 * Provides the site base URL (import.meta.env.BASE_URL) to all
 * descendant React components via context.
 *
 * Usage:
 * - In Astro pages/layouts (where import.meta.env.BASE_URL IS substituted
 *   by Vite), wrap React components with:
 *     <BaseUrlProvider baseUrl={import.meta.env.BASE_URL}>
 *       <YourComponent />
 *     </BaseUrlProvider>
 *
 * - In client:load React components (local site files), wrap the return:
 *     const BASE_URL = import.meta.env.BASE_URL;
 *     return <BaseUrlProvider baseUrl={BASE_URL}>...</BaseUrlProvider>;
 *
 * Note: npm package code is SSR-externalized by Vite and does NOT receive
 * import.meta.env.BASE_URL substitution. This context is the correct way
 * to propagate the base URL into package components.
 */
export const BaseUrlContext = createContext("/");
export function useBaseUrl() {
    return useContext(BaseUrlContext);
}
export function BaseUrlProvider({ baseUrl, children, }) {
    return (_jsx(BaseUrlContext.Provider, { value: baseUrl, children: children }));
}
