import { User, Buildings, CpuBolt, CodeSquare, TestTube, CalendarMark, Document2, } from "@solar-icons/react-perf/LineDuotone";
/**
 * Type icon (line-duotone) for each entity type. Mirrors the existing
 * Avatar `TypeIcon` map; `press` reuses the `Document2` glyph that
 * was previously labelled `document`.
 */
const ENTITY_ICONS = {
    person: User,
    organization: Buildings,
    hardware: CpuBolt,
    software: CodeSquare,
    research: TestTube,
    event: CalendarMark,
    press: Document2,
};
/**
 * Tailwind classes for a fallback-avatar tinted background. Each
 * entity type gets a subtle gradient that reads in both light and
 * dark modes. The two theme-aware tints (`accent-one`, `special-*`)
 * use site theme variables; the colored tints use opacity-modified
 * fixed hues that look correct against either surface.
 *
 * Use alongside `getEntityIconColor` for the glyph on top.
 */
const ENTITY_FALLBACK_BG = {
    person: "bg-linear-to-br from-accent-one/20 to-accent-two/20",
    organization: "bg-linear-to-br from-special-lighter to-special-light",
    hardware: "bg-linear-to-br from-blue-500/20 to-blue-600/20",
    software: "bg-linear-to-br from-green-500/20 to-green-600/20",
    research: "bg-linear-to-br from-purple-500/20 to-purple-600/20",
    event: "bg-linear-to-br from-orange-500/20 to-orange-600/20",
    press: "bg-linear-to-br from-gray-500/20 to-gray-600/20",
};
/**
 * Theme-aware icon color for entity fallback avatars. Uses
 * `text-accent-base` which flips with the active theme, at reduced
 * opacity for a softer "placeholder" feel.
 */
const ENTITY_ICON_COLOR = "text-accent-base opacity-60";
export function getEntityIcon(type) {
    return ENTITY_ICONS[type];
}
/**
 * Derive a 1–2 character "initials" string from a name. Used as the
 * fallback inside person-type avatars on both small cards and detail
 * heroes — both surfaces should produce the same result for the same
 * input so a person's card preview and their detail-page hero match.
 *
 * Rules:
 *  - Multi-word names → first letter of the first two words (e.g.
 *    "Naomi Fitter" → "NF", "Dr. Foo Bar" → "DF").
 *  - Single-word names → first two characters of that word (e.g.
 *    "Madonna" → "MA").
 *  - Returned uppercased.
 */
export function getEntityInitials(name) {
    if (!name)
        return "";
    const words = name.trim().split(/\s+/).filter(Boolean);
    if (words.length === 0)
        return "";
    if (words.length === 1) {
        return (words[0]?.substring(0, 2) || "").toUpperCase();
    }
    return words
        .slice(0, 2)
        .map((word) => word[0] ?? "")
        .join("")
        .toUpperCase();
}
export function getEntityFallbackBg(type) {
    return ENTITY_FALLBACK_BG[type];
}
export function getEntityIconColor() {
    return ENTITY_ICON_COLOR;
}
/**
 * One-shot helper: returns the icon component, fallback background
 * classes, and icon color classes for a given entity type. Callers
 * that need only the JSX-ready bundle (most of them) can use this
 * instead of three separate calls.
 */
export function getEntityVisuals(type) {
    return {
        Icon: ENTITY_ICONS[type],
        bgClass: ENTITY_FALLBACK_BG[type],
        iconColorClass: ENTITY_ICON_COLOR,
    };
}
