/**
 * The "featuring" object replaces the older boolean/array `featuredOn`
 * flag with a temporal record. Three meaningful states:
 *
 *   - `featuring` absent: not featured anywhere.
 *   - `featuring: { onSites }` with no dates: evergreen featured on
 *     those sites (the previous `featuredOn` semantics).
 *   - `featuring: { onSites, fromDate?, toDate? }`: featured during
 *     the date window on those sites. Press and awards inherit a
 *     sensible anchor (publishDate / awardDate) and a 4-month default
 *     duration when only one bound is specified — see `isFeatured`.
 *
 * Lives on every collection that participates in featured ordering:
 * people, organizations, hardware, software, research, events, press,
 * awards.
 */
import { getActiveSiteKey } from "./active-site.js";
/**
 * Default duration of a featuring window when only one bound is
 * explicit. Used by `isFeatured` when the caller supplies an
 * `anchorDate` (e.g. a press item's `publishDate`) without an explicit
 * `toDate`. Approximately four months.
 */
export const DEFAULT_FEATURING_DURATION_MS = 4 * 30 * 24 * 60 * 60 * 1000;
/**
 * Core resolver: given a `featuring` value and optional context,
 * returns true iff the entity is currently featured.
 *
 * `siteKey` is optional. When omitted, the check is "featured on at
 * least one site during the active window" — useful for card
 * converters that don't know which site they're rendering on. When
 * provided, narrows to that site.
 *
 * `anchorDate` lets press and awards anchor the window to their
 * `publishDate` / `awardDate` even when `featuring.fromDate` is
 * unset. Combined with `DEFAULT_FEATURING_DURATION_MS`, this gives a
 * "featured starting at publication, ending four months later" default
 * for press/awards without forcing every entry to specify both dates.
 *
 * Entities (people, hardware, etc.) without an `anchorDate` and
 * without explicit dates are treated as evergreen featured — the
 * previous `featuredOn` semantics, preserved exactly.
 */
export function isFeatured(featuring, siteKey, options = {}) {
    if (!featuring)
        return false;
    if (!Array.isArray(featuring.onSites) || featuring.onSites.length === 0)
        return false;
    if (siteKey && !featuring.onSites.includes(siteKey))
        return false;
    const now = options.now ?? new Date();
    const anchor = options.anchorDate
        ? new Date(options.anchorDate)
        : undefined;
    const fromDate = featuring.fromDate
        ? new Date(featuring.fromDate)
        : anchor;
    let toDate;
    if (featuring.toDate) {
        toDate = new Date(featuring.toDate);
    }
    else if (fromDate) {
        // Apply the default 4-month duration when one bound exists but
        // not the other. With an anchorDate this gives press/awards an
        // automatic temporal window; without an anchor it has no effect
        // (entities stay evergreen).
        toDate = new Date(fromDate.getTime() + DEFAULT_FEATURING_DURATION_MS);
    }
    if (fromDate && now < fromDate)
        return false;
    if (toDate && now > toDate)
        return false;
    return true;
}
function readFeaturing(item) {
    if (!item || typeof item !== "object")
        return undefined;
    const withData = item;
    return withData.data?.featuring ?? withData.featuring;
}
/**
 * Press type tags that mark an entry as participating in the
 * publishDate-driven anchor semantics. We deliberately don't treat
 * a bare `publishDate` field as an anchor everywhere — research,
 * hardware, and software entries also carry `publishDate` (meaning
 * "released on"), and using those as featuring anchors would expire
 * evergreen entity featuring after the 4-month default duration.
 */
const PRESS_TYPE_TAGS = new Set([
    "announcement",
    "publication",
    "story",
]);
function readAnchor(item) {
    if (!item || typeof item !== "object")
        return undefined;
    const withData = item;
    // Awards: always anchor on `awardDate` (a field only awards have).
    const awardDate = withData.data?.awardDate ?? withData.awardDate;
    if (awardDate)
        return awardDate;
    // Press: anchor on `publishDate` only when the entry's `type` is
    // one of the press discriminator values. Research entries also
    // have a `type` field, but its values (`program`, `fellowship`,
    // etc.) don't intersect with press's set — so this check is safe.
    const type = withData.data?.type ?? withData.type;
    if (typeof type === "string" && PRESS_TYPE_TAGS.has(type)) {
        const publishDate = withData.data?.publishDate ?? withData.publishDate;
        if (publishDate)
            return publishDate;
    }
    // Everything else (entities — people, hardware, software,
    // research, organizations, events): no anchor. Evergreen featuring
    // stays evergreen.
    return undefined;
}
/**
 * Sugar wrapper that reads `featuring` (and an appropriate
 * anchorDate) from an Astro collection entry or a plain object, then
 * delegates to `isFeatured`.
 *
 * `siteKey` selects which site to ask about, defaulting to the build's
 * own. Omitting it used to mean "featured on *any* site", which is
 * almost never what a caller wants and is indistinguishable from the
 * correct call at the call site — so every listing helper that forgot
 * the argument quietly reported another site's featured entries as
 * featured here. Sites publish their key at module load
 * (`setActiveSiteKey`), so the default is right by the time any page
 * renders.
 *
 * There is no way to ask the cross-site question *through this
 * function*, and that is deliberate. A JavaScript default applies to an
 * explicit `undefined` exactly as it does to an omitted argument, so
 * `isFeaturedOnSite(item, undefined)` also scopes to the active site.
 * Distinguishing the two (via `arguments.length`) would change nothing
 * for direct callers and would hand the four payload builders that
 * *forward* an optional `siteKey` straight back the bug this default
 * exists to fix — they pass `undefined` whenever the site omits the
 * option. For a genuinely cross-site check, call `isFeatured` with no
 * site key.
 */
export function isFeaturedOnSite(item, siteKey = getActiveSiteKey(), now) {
    const featuring = readFeaturing(item);
    if (!featuring)
        return false;
    return isFeatured(featuring, siteKey, {
        anchorDate: readAnchor(item),
        now,
    });
}
/**
 * Stable-sorts a list so currently-featured entries come first,
 * preserving the original relative order within each tier. `siteKey`
 * defaults to this build's site — including when a caller forwards an
 * explicit `undefined` — for the reasons given on `isFeaturedOnSite`.
 *
 * Modern JS sort is stable, so within "featured" and "not featured"
 * tiers the input order is preserved.
 */
export function sortFeaturedFirst(items, siteKey = getActiveSiteKey()) {
    return [...items].sort((a, b) => {
        return (Number(isFeaturedOnSite(b, siteKey)) -
            Number(isFeaturedOnSite(a, siteKey)));
    });
}
